using Test
using OpSum
using OpSum: instantiate, mpo_terms, mpo, irrep_mpo_tensors, nterms_raw, total, opsum,
    Terms
using TensorKit
using Random: Xoshiro, shuffle
using MatrixAlgebraKit: truncrank, trunctol
using LinearAlgebra: dot, norm

include(joinpath(@__DIR__, "testutils.jl"))   # physmatrix, densedim

# Property tests over random term sums: terms are generated by `project`ing random symmetric `K`-site
# operators, which sweeps every representable (letters, caterpillar tree) combination at once, so the
# running-charge component of the sweep's state is actually exercised.

const PROPERTY_SPACES = [
    "Trivial" => unitbasis(ℂ^2),
    "U1Irrep" => unitbasis(Rep[U₁](0 => 1, 1 => 1)),
    "SU2Irrep" => unitbasis(SU2Space(1 // 2 => 1)),
    "FermionNumber" => unitbasis(Vect[FermionNumber](0 => 1, 1 => 1)),
]

# `K` random ascending sites out of `1:N`
randsites(rng, N, K) = sort!(shuffle(rng, collect(1:N))[1:K])

"""
A random charge-neutral operator on `N` sites: one `project`ed random block per entry of `Ks`.
`K = 0` contributes the identity term, which is the one shape `project` cannot produce.
"""
function random_termsum(rng, B, N, Ks)
    V = space(B)
    I = sectortype(V)
    parts = Terms{I}[]
    for K in Ks
        if iszero(K)
            push!(parts, scalarop(randn(rng, ComplexF64), B)[1])
            continue
        end
        sites = randsites(rng, N, K)
        Vs = fill(V, K)
        h = randn(rng, ComplexF64, foldl(⊗, Vs) ← foldl(⊗, Vs))
        push!(parts, project(h, B)[sites...])
    end
    return opsum(parts)
end

@testset "random term sums compress losslessly — $name" for (name, B) in PROPERTY_SPACES
    V = space(B)
    N = 5
    sites = fill(B, N)
    for seed in (1, 2, 3)
        rng = Xoshiro(seed)
        H = random_termsum(rng, B, N, [0, 1, 1, 2, 2, 2, 3, 3])
        @test !isempty(H)
        @test all(t -> total(t) == unit(sectortype(V)), H)
        @test islossless(opsum(sites, H))
        Ws, secs = reduced(mpo(opsum(sites, H)))
        @test length(secs) == N
        @test secs[N] == [unit(sectortype(V))]
        @test all(length(s) <= nterms_raw(H) + 1 for s in secs)
        # the lossless SVD rank is bounded by the cover (`islossless` does not apply to SVD bases; see below)
        for alg in (SVDBondAlgorithm(), SVDBondAlgorithm(; sweep = SequentialSVD))
            _, ssvd = reduced(mpo(opsum(sites, H), alg))
            @test all(densedim(ssvd, b) <= densedim(secs, b) for b in 1:N)
        end
    end
end

@testset "K = 4 terms — $name" for (name, B) in PROPERTY_SPACES
    V = space(B)
    # a four-site term is the first with two caterpillar inner lines
    N = 5
    sites = fill(B, N)
    rng = Xoshiro(7)
    H = random_termsum(rng, B, N, [4, 4, 2])
    @test !isempty(H)
    @test islossless(opsum(sites, H))
    @test maximum(length(t.sites) for t in H) == 4
    Ws, secs = reduced(mpo(opsum(sites, H)))
    @test secs[N] == [unit(sectortype(V))]
    Js = jordan_mpo_tensors(opsum(sites, H))
    @test length(Js) == N
    @test size(Js[1], 1) == 1 && size(Js[N], 4) == 1
end

@testset "random term sums assemble to the same tensor — $name" for (name, B) in
    PROPERTY_SPACES[[3, 4]]
    # dense oracle on the sectors where a fusion coefficient or braiding sign could be wrong (one size
    # and seed: contraction costs an `ncon` specialization per length and sectortype)
    V = space(B)
    N = 4
    sites = fill(B, N)
    H = random_termsum(Xoshiro(11), B, N, [0, 1, 2, 2, 3])
    exact = instantiate(opsum(sites, H))
    Ws, secs = reduced(mpo(opsum(sites, H)))
    @test mpo_tensormap(irrep_mpo_tensors(Ws, secs, fill(B, N))) ≈ exact
    @test mpo_tensormap(map(TensorMap, jordan_mpo_tensors(opsum(sites, H)))) ≈ exact
    for alg in (SVDBondAlgorithm(), SVDBondAlgorithm(; sweep = SequentialSVD))
        Wsv, ssv = reduced(mpo(opsum(sites, H), alg))
        @test mpo_tensormap(irrep_mpo_tensors(Wsv, ssv, fill(B, N))) ≈ exact
    end
end

# Truncation quality: the error must be small, not just nonzero.

# long-range Heisenberg chain: a real singular-value spectrum to truncate
function powerlaw_chain(B, N; α = 2.0)
    S = spinvector(B)
    return opsum(abs(m - n)^(-α) * dot(S[n], S[m]) for n in 1:(N - 1) for m in (n + 1):N)
end

const TRUNC_V = SU2Space(1 // 2 => 1)
const TRUNC_N = 5
const TRUNC_B = unitbasis(TRUNC_V)
const TRUNC_H = powerlaw_chain(TRUNC_B, TRUNC_N)
const TRUNC_LAT = FiniteChain(TRUNC_B, TRUNC_N)
const TRUNC_EXACT = instantiate(opsum(TRUNC_LAT, TRUNC_H))
const TRUNC_NORM = norm(TRUNC_EXACT)

# Relative error of the assembled MPO against the exact operator (`islossless` is unreliable for SVD bases).
function mpo_relerror(alg)
    Ws, secs = reduced(mpo(opsum(TRUNC_LAT, TRUNC_H), alg))
    Os = irrep_mpo_tensors(Ws, secs, fill(TRUNC_B, TRUNC_N))
    return norm(mpo_tensormap(Os) - TRUNC_EXACT) / TRUNC_NORM
end

nondecreasing(xs) = all(xs[i + 1] <= xs[i] + 1.0e-12 for i in 1:(length(xs) - 1))

@testset "truncation error decreases with the retained rank" begin
    errs = [mpo_relerror(SVDBondAlgorithm(truncrank(k))) for k in 1:6]
    @test nondecreasing(errs)
    # `truncrank` counts quantum dimensions, so rank 1 cannot hold a spin-1 channel and the MPO collapses to zero
    @test errs[1] ≈ 1
    @test errs[end] < 0.1
    @test mpo_relerror(SVDBondAlgorithm(truncrank(1000))) < 1.0e-10
end

@testset "trunctol at the API level" begin
    _, sfull = reduced(mpo(opsum(TRUNC_LAT, TRUNC_H), SVDBondAlgorithm()))

    _, stight = reduced(mpo(opsum(TRUNC_LAT, TRUNC_H), SVDBondAlgorithm(trunctol(; rtol = 1.0e-14))))
    @test [length(s) for s in stight] == [length(s) for s in sfull]
    @test mpo_relerror(SVDBondAlgorithm(trunctol(; rtol = 1.0e-14))) < 1.0e-10

    # a loose tolerance drops channels with error of the tolerance's order
    alg = SVDBondAlgorithm(trunctol(; rtol = 0.1))
    _, sloose = reduced(mpo(opsum(TRUNC_LAT, TRUNC_H), alg))
    @test any(length(sloose[b]) < length(sfull[b]) for b in 1:(TRUNC_N - 1))
    @test all(length(sloose[b]) <= length(sfull[b]) for b in 1:TRUNC_N)
    @test mpo_relerror(alg) < 0.1

    @test mpo_relerror(SVDBondAlgorithm(truncrank(1000) & trunctol(; rtol = 1.0e-14))) < 1.0e-10
end
